),
projects_norm AS (
  SELECT
    p.id,
    p.name,
    lower(
      trim(
        regexp_replace(
          regexp_replace(
            regexp_replace(trim(regexp_replace(p.name, '\s+', ' ', 'g')), '\s+([א-ת])$', '\1'),
            '([0-9])\s+([א-ת])', '\1\2', 'g'
          ),
          '\s*-\s*', ' ', 'g'
        )
      )
    ) AS norm_name
  FROM projects p
  WHERE p.client_id = '7573f5ad-70e5-4357-8fef-1d96ec38d169'::uuid
    AND p.is_active = true
),
matched AS (
  SELECT
    pr.*,
    pn.id AS project_id,
    pn.name AS db_project_name
  FROM pdf_rows pr
  JOIN projects_norm pn ON pn.norm_name = pr.pdf_project_norm
),
to_insert AS (
  SELECT m.*
  FROM matched m
  WHERE NOT EXISTS (
    SELECT 1 FROM residents r
    WHERE r.client_id = '7573f5ad-70e5-4357-8fef-1d96ec38d169'::uuid
      AND r.deleted_at IS NULL
      AND r.project_id = m.project_id
      AND (
        (m.normalized_phone IS NOT NULL AND r.normalized_phone = m.normalized_phone)
        OR (
          m.normalized_phone IS NULL
          AND lower(trim(coalesce(r.apartment_number, ''))) = lower(trim(m.apartment_number))
          AND lower(trim(r.full_name)) = lower(trim(m.full_name))
        )
      )
  )
)
INSERT INTO residents (
  client_id,
  project_id,
  full_name,
  phone,
  normalized_phone,
  email,
  apartment_number,
  notes,
  is_renter
)
SELECT
  '7573f5ad-70e5-4357-8fef-1d96ec38d169'::uuid,
  project_id,
  full_name,
  phone,
  normalized_phone,
  email,
  NULLIF(trim(apartment_number), ''),
  notes,
  is_renter
FROM to_insert;

COMMIT;

